sys_ux_data_broker_transform.script:
function transform(input) {
    var result = []; // Array to store publisher data in the required format
    var gr = new GlideRecord('cmdb_software_product_model');

    // If input is provided, use it to filter the query (e.g., by sys_id)
    if (input && input.sys_id) {
        gr.addQuery('sys_id', input.sys_id);
    }
    // Add more conditions based on input if needed, e.g., input.model_name
    else if (input && input.model_name) {
        gr.addQuery('name', input.model_name);
    }

    gr.query(); // Execute the query

    while (gr.next()) {
        var publisherSysId = gr.getValue('manufacturer'); // Get the sys_id from manufacturer
        if (publisherSysId) {
            var companyGr = new GlideRecord('core_company');
            if (companyGr.get(publisherSysId)) {
                var publisherName = companyGr.getValue('name'); // Get the publisher name
                if (publisherName && !result.some(item => item[0].id === publisherName)) { // Avoid duplicates
                    // Push the publisher name in the required nested structure
                    result.push([
                        {
                            "id": publisherName,
                            "label": publisherName
                        }
                    ]);
                }
            }
        }
    }

	// gs.log('okokokok',JSON.stringify(result,null,2));

    // Return the formatted array, or a default message if no publishers found
    return result.length > 0 ? result : [[{"id": "No publishers found", "label": "No publishers found"}]];
}
